import { formatSlot } from './format-slot.js';

/**
 * The stores that still have same-day capacity, each with its open slots as people read them (STORY-031-1):
 * storesSameDayCapacity([{ id: 'a', slots: [{ start: '18:00', end: '19:00', left: 2 }] }]) → [{ id: 'a', slots: ['18:00–19:00'] }].
 */
export const storesSameDayCapacity = (stores) => stores
  .map((store) => ({ id: store.id, slots: store.slots.filter((s) => s.left > 0).map((s) => formatSlot(s.start, s.end)) }))
  .filter((store) => store.slots.length > 0);

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { storesSameDayCapacity } from '../stores-same-day-capacity.js';

const stores = [
  { id: 'a', slots: [{ start: '18:00', end: '19:00', left: 1 }, { start: '19:00', end: '20:00', left: 0 }] },
  { id: 'b', slots: [{ start: '18:00', end: '19:00', left: 0 }] },
];

test('TC-031-1-1: the last slot goes to one customer; the store shows the next one', () => {
  assert.deepEqual(storesSameDayCapacity(stores), [{ id: 'a', slots: ['18:00–19:00'] }]);
});

test('TC-031-1-2: the customer app gets each store with capacity as { id, slots }', () => {
  assert.deepEqual(Object.keys(storesSameDayCapacity(stores)[0]), ['id', 'slots']);
});

test('TC-031-1-3: the store manager console reads the same stores as customers', () => {
  assert.equal(storesSameDayCapacity(stores).length, 1);
});

test('TC-031-1-5: slots come back as people read them', () => {
  assert.deepEqual(storesSameDayCapacity(stores)[0].slots, ['18:00–19:00']);
});

test('TC-031-1-6: a store with no capacity left is not listed', () => {
  assert.equal(storesSameDayCapacity(stores).some((s) => s.id === 'b'), false);
});

test('TC-031-1-7: a store whose inventory has no slots lists nothing', () => {
  assert.deepEqual(storesSameDayCapacity([{ id: 'c', slots: [] }]), []);
});

test('TC-031-1-8: the delivery planner gets the stores in the order it gave them', () => {
  const two = [{ id: 'y', slots: [{ start: '18:00', end: '19:00', left: 1 }] }, { id: 'x', slots: [{ start: '18:00', end: '19:00', left: 2 }] }];
  assert.deepEqual(storesSameDayCapacity(two).map((s) => s.id), ['y', 'x']);
});

test('TC-031-1-9: see which stores still have same-day capacity, from start to end', () => {
  const shown = storesSameDayCapacity(stores);
  assert.deepEqual(shown.map((s) => s.id), ['a']);
});

test('TC-031-1-10: a thousand stores are listed in under 300 ms', () => {
  const many = Array.from({ length: 1000 }, (_, i) => ({ id: `s${i}`, slots: [{ start: '18:00', end: '19:00', left: 1 }] }));
  const started = performance.now();
  storesSameDayCapacity(many);
  assert.ok(performance.now() - started < 300);
});

